1	import { Card } from "@/components/ui/Card";
2	import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
3	import { ReportCard } from "@/components/admin/ReportCard";
4	import { requireRole } from "@/lib/auth";
5	import { listReports, getProfilesByIds } from "@/lib/db/queries";
6	import { shortDate } from "@/lib/time";
7	import { t } from "@/lib/i18n";
8	
9	export const metadata = { title: `${t("admin.reportsTitle")} · ${t("app.name")}` };
10	
11	export default async function AdminReportsPage() {
12	  await requireRole("admin");
13	  const reports = await listReports();
14	
15	  const ids = Array.from(
16	    new Set(
17	      reports.flatMap((r) => [r.reporter_id, r.target_id].filter(Boolean)),
18	    ),
19	  ) as string[];
20	  const profiles = await getProfilesByIds(ids);
21	  const nameFor = (id: string | null) =>
22	    (id && (profiles.get(id)?.full_name || profiles.get(id)?.email)) || "—";
23	
24	  return (
25	    <div className="flex flex-col gap-6">
26	      <DashboardHeader
27	        title={t("admin.reportsTitle")}
28	        description={t("admin.reportsSubtitle")}
29	      />
30	
31	      {reports.length === 0 ? (
32	        <Card>
33	          <p className="text-base text-ink-soft">{t("admin.reportsNone")}</p>
34	        </Card>
35	      ) : (
36	        <ul className="flex flex-col gap-4">
37	          {reports.map((r) => (
38	            <ReportCard
39	              key={r.id}
40	              report={{
41	                id: r.id,
42	                reason: r.reason,
43	                status: r.status,
44	                whenLabel: shortDate(r.created_at),
45	                reporterName: nameFor(r.reporter_id),
46	                targetId: r.target_id,
47	                targetName: r.target_id ? nameFor(r.target_id) : null,
48	              }}
49	            />
50	          ))}
51	        </ul>
52	      )}
53	    </div>
54	  );
55	}
